(6237479, 922258, 96751, '<td valign="top">Nice!!  Sharp and rich.  Just looks a TEENY bit tilted to me.</td>', 'Nice!!  Sharp and rich.  Just looks a TEENY bit tilted to me.', '2010-11-29 13:45:55.000000', NULL, 1),
(6237480, 921764, 96751, '<td valign="top">Awwww.  Cat''s eyes are so strange, aren''t they?</td>', 'Awwww.  Cat''s eyes are so strange, aren''t they?', '2010-11-29 13:46:19.000000', NULL, 1),
(6237481, 922521, 96751, '<td valign="top">And how many tries did this take??  They''re fun to do though.</td>', 'And how many tries did this take??  They''re fun to do though.', '2010-11-29 13:47:07.000000', NULL, 1),
(6237482, 922597, 96751, '<td valign="top">I love all the delicate lines of the twigs, and the little flecks of orange from the remaining leaves.  I think a tighter crop could have improved the image.</td>', 'I love all the delicate lines of the twigs, and the little flecks of orange from the remaining leaves.  I think a tighter crop could have improved the image.', '2010-11-29 13:47:57.000000', NULL, 1),
(6237484, 921997, 96751, '<td valign="top">The lighting on this is so splendid.  I love the ghostly flare on the bottom, and the delicate shapes of the leaves.</td>', 'The lighting on this is so splendid.  I love the ghostly flare on the bottom, and the delicate shapes of the leaves.', '2010-11-29 13:48:30.000000', NULL, 1),
(6237485, 922353, 96751, '<td valign="top">Well, I wouldn''t wear them but... that smile of his really makes this shot.</td>', 'Well, I wouldn''t wear them but... that smile of his really makes this shot.', '2010-11-29 13:49:07.000000', NULL, 1),
(6237486, 922443, 96751, '<td valign="top">I''ve never seen frost on a flower before, and now there are at least two flowers with it.  Very cool!</td>', 'I''ve never seen frost on a flower before, and now there are at least two flowers with it.  Very cool!', '2010-11-29 13:49:37.000000', NULL, 1),
(6237488, 922562, 96751, '<td valign="top">Like a visual haiku!  Gorgeous.  The mix of colors, shapes and textures is perfect.</td>', 'Like a visual haiku!  Gorgeous.  The mix of colors, shapes and textures is perfect.', '2010-11-29 13:50:10.000000', NULL, 1),
(6237489, 922598, 96751, '<td valign="top">So eloquent with such minimal elements.</td>', 'So eloquent with such minimal elements.', '2010-11-29 13:50:49.000000', NULL, 1),
(6237490, 922524, 96751, '<td valign="top">What an amazing sky.</td>', 'What an amazing sky.', '2010-11-29 13:51:22.000000', NULL, 1),
(6237492, 922400, 96751, '<td valign="top">From another planet!!  This is terrific.  I''m really curious about that ball thing though.  It looks like it has an attachment on the back (in the indented dimple), which is also not an ashy/organic shape.  Fabulous lighting.</td>', 'From another planet!!  This is terrific.  I''m really curious about that ball thing though.  It looks like it has an attachment on the back (in the indented dimple), which is also not an ashy/organic shape.  Fabulous lighting.', '2010-11-29 13:53:03.000000', NULL, 1),
(6237494, 922367, 96751, '<td valign="top">Lovely street scene.</td>', 'Lovely street scene.', '2010-11-29 13:57:13.000000', NULL, 1),
(6237508, 922365, 54446, '<td valign="top">Beautiful scene, but looks rose pink to me.</td>', 'Beautiful scene, but looks rose pink to me.', '2010-11-29 14:16:11.000000', NULL, 1),
(6237539, 922575, 70484, '<td valign="top">Beautiful composition! The colors are rich and true!</td>', 'Beautiful composition! The colors are rich and true!', '2010-11-29 14:58:43.000000', NULL, 1),
(6237542, 922394, 70484, '<td valign="top">Beautiful colors and I love that you used an ornament for the "vase". Nicely captured.</td>', 'Beautiful colors and I love that you used an ornament for the "vase". Nicely captured.', '2010-11-29 14:59:30.000000', NULL, 1),
(6237545, 922520, 70484, '<td valign="top">Amazing clarity, color and composition! Love it!!!</td>', 'Amazing clarity, color and composition! Love it!!!', '2010-11-29 15:00:20.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6237553, 921966, 70484, '<td valign="top">Beautiful!!!! I absolutely love it!!! I would definitely hang it in my house. I think this is a great capture. One of my favorites! The abstracty feel really adds to this capture.</td>', 'Beautiful!!!! I absolutely love it!!! I would definitely hang it in my house. I think this is a great capture. One of my favorites! The abstracty feel really adds to this capture.', '2010-11-29 15:05:28.000000', NULL, 1),
(6237556, 922331, 70484, '<td valign="top">Great composition! First, she is a cutie pie, and what a smile!!! The whole picture just makes me want to be happy! I love that about it!! Great choice on the black pants and boots and white coat. The pants really act as an anchor in this photo and the white coat adds to the lightness and really makes the scarf and hat pop. The styling and model are perfect! One of my faves in this challenge.</td>', 'Great composition! First, she is a cutie pie, and what a smile!!! The whole picture just makes me want to be happy! I love that about it!! Great choice on the black pants and boots and white coat. The pants really act as an anchor in this photo and the white coat adds to the lightness and really makes the scarf and hat pop. The styling and model are perfect! One of my faves in this challenge.', '2010-11-29 15:09:39.000000', NULL, 1),
(6237559, 922572, 70484, '<td valign="top">First thing I thought of when I saw this was Audrey Hepburn. The model here is beautiful and timeless. Great capture and good use of negative space to create feeling. Nicely done.</td>', 'First thing I thought of when I saw this was Audrey Hepburn. The model here is beautiful and timeless. Great capture and good use of negative space to create feeling. Nicely done.', '2010-11-29 15:11:16.000000', NULL, 1),
(6237561, 921882, 115827, '<td valign="top">hahahaha,,,,,,,,,,,,,,,,,,,</td>', 'hahahaha,,,,,,,,,,,,,,,,,,,', '2010-11-29 15:12:35.000000', NULL, 1),
(6237563, 921704, 70484, '<td valign="top">Although this is a good portrait and I like that he isn''t lifeless, but has an expressive face, I don''t know that I really get Orange from this shot. I can see the overtones and I like the post processing, but it doesn''t really call out to me for this challenge. I imagine I would have scored it higher in a portrait challenge, but with that being said, I am bumping it up this second time through for out of the box and creativeness.</td>', 'Although this is a good portrait and I like that he isn''t lifeless, but has an expressive face, I don''t know that I really get Orange from this shot. I can see the overtones and I like the post processing, but it doesn''t really call out to me for this challenge. I imagine I would have scored it higher in a portrait challenge, but with that being said, I am bumping it up this second time through for out of the box and creativeness.', '2010-11-29 15:15:20.000000', NULL, 1),
(6237564, 922031, 70484, '<td valign="top">Yes, a little cheesy, but that doesn''t bother me. I like the full frame orange color effect. However, in my opinion, this seems a little out of focus and maybe even a little underexposed. I don''t know exactly what it is (I am still learning all of this), but if it were a little clearer and exposed a little differently I would have scored it a bit higher, but you definitely met the challenge!</td>', 'Yes, a little cheesy, but that doesn''t bother me. I like the full frame orange color effect. However, in my opinion, this seems a little out of focus and maybe even a little underexposed. I don''t know exactly what it is (I am still learning all of this), but if it were a little clearer and exposed a little differently I would have scored it a bit higher, but you definitely met the challenge!', '2010-11-29 15:19:17.000000', NULL, 1),
(6237565, 922195, 70484, '<td valign="top">Typically I really like the abstract photo, but something on this just feels off. I am not exactly sure what it is. I like the double effect of the horizon, but it seems that there is some reflection or something over the bottom right quarter of the photo that seems to be distracting from the image. Without this reflection I feel that the abstract image would make a greater impact.</td>', 'Typically I really like the abstract photo, but something on this just feels off. I am not exactly sure what it is. I like the double effect of the horizon, but it seems that there is some reflection or something over the bottom right quarter of the photo that seems to be distracting from the image. Without this reflection I feel that the abstract image would make a greater impact.', '2010-11-29 15:24:11.000000', NULL, 1),
(6237569, 921703, 70484, '<td valign="top">I''m not sure that I am seeing a lot of orange in this picture.  I see the light from the door or window to the left and the tips if the leaves on the left, but not much more. I think it may be a tad of a stretch for this challenge.</td>', 'I''m not sure that I am seeing a lot of orange in this picture.  I see the light from the door or window to the left and the tips if the leaves on the left, but not much more. I think it may be a tad of a stretch for this challenge.', '2010-11-29 15:27:24.000000', NULL, 1),
